import json, os, re, copy

def parse_grid(text, dims):
    h, w = map(int, dims.split('x'))
    rows = []
    in = False
    for line in text.split('\n'):
        if not line.strip() or (in and not line.strip()):
            continue
        if 'input' in line:
            in = True
            rows = []
        elif 'output' in line:
            in = False
        elif rows:
            rows.append([int(x) for x in line.split()])
    return rows

def load_and_parse(text):
    demos = re.findall(r'Demo pair (\d+) input|Demo pair (\d+) output|Test input \((\d+)x(\d+)\):(.*?)(?=\n\s*(Demo|After|Task|Wrong|\n))', text, re.DOTALL)
    result = {}
    demo_id = 0
    in_grid = False
