    has_dims = False

    for match in re.finditer(r'(Demo pair (\d+) (?:input|output)) \((\d+)x(\d+)\):(.*?)(?=\n|\s*Demo|\s*Test|\s*$)', text, re.DOTALL):
        k, demo_num, h, w, grid_text = match
        grid = [[int(x) for x in g.split()] for g in grid_text.strip().split('\n')]
        result[f'demo_{demo_num}'] = grid

    return result

