# Let me take a completely different approach
# What if anchors project "rays" horizontally?
# - Anchors in row R project left and right rays
# - Ray stops at background or at row R+1's anchors

def apply_ray_cast(grid):
    h, w = len(grid), len(grid[0])

    output = [[grid[r][c] for c in range(w)] for r in range(h)]
    bg_color = grid[0][0] 
    fill_color = 3
    anchor_color = 5

    for r in range(h):
        row_anchors = [c for c in range(w) if grid[r][c] == anchor_color]
        row_anchors_below = [c for c in range(w) if grid[r+1][c] == anchor_color] if r + 1 < h else []

        # Project rays from each anchor
        for r_anchor in row_anchors:
            # Project left ray
            for c in range(r_anchor - 1, -1, -1):
                if output[r][c] == bg_color:
                    if r_anchor - 1 in row_anchors_below:
                        # Stop at next-left anchor below
                        if r + 1 >= 0 and row_anchors_below:
                            next_left = max([c for c in row_anchors_below if c < r_anchor])
                            if c >= next_left:
                                output[r][c] = fill_color
                            else:
                                output[r][c] = bg_color
                        else:
                            continue
                    else:
                        output[r][c] = fill_color
                else:
                    break

            # Project right ray
            for c in range(r_anchor + 1, w):
                if output[r][c] == bg_color:
                    # Check if this column has anchor in row below
                    if c in row_anchors_below:
                        output[r][c] = fill_color
                    else:
                        # Limit: don't go beyond rightmost anchor in this row
                        if r + 1 >= 0 and row_anchors_below:
                           rightmost = max(row_anchors_below)
                           if c > rightmost:
                               output[r][c] = bg_color
                           else:
                               output[r][c] = fill_color
                        else:
                           output[r][c] = fill_color
                else:
                    break

    return output

