def apply_simple_rule_v2(grid):
    h, w = len(grid), len(grid[0])
    output = [[grid[r][c] for c in range(w)] for r in range(h)]
    bg = grid[0][0]
    anchor = 5
    fill = 3

    for r in range(h):
        anchors = [c for c in range(w) if grid[r][c] == anchor]
        r_down = grid[r+1] if r+1 < h else None
        if r_down:
            anchors_down = [c for c in range(w) if r_down[c] == anchor]

        # Fill between consecutive anchors in this row
        for i in range(len(anchors) - 1):
            left, right = anchors[i], anchors[i+1]
            for c in range(left + 1, right):
                if output[r][c] == bg:
                    output[r][c] = fill

        # Fill after rightmost anchor if row below has anchors to the right
        if anchors_down and anchors_down[-1] > anchors[-1]:
            for c in range(anchors[-1] + 1, min(w, anchors_down[-1] + 3)):
                if output[r][c] == bg:
                    output[r][c] = fill
        # Fill before leftmost anchor if row below has anchors to the left of this row's anchors
        elif anchors_down and anchors_down[0] < (max(anchors) - 3 if anchors else 0):
            for c in range(max(0, anchors_down[0] - 2), anchors[0]):
                if output[r][c] == bg:
                    output[r][c] = fill

    return output

