def solve_final_v2(grid):
    """
    Rule summary:
    1. For rows with >= 2 anchors: fill between each consecutive pair
    2. For rows with single anchor: check if next row has anchor at (single_anchor + 1)
       - If yes: NO fill (Row 0 case)
       - If no: fill 2 columns to the right (Row 3 case) - only looks at LAST row
    """
    h, w = len(grid), len(grid[0])
    result = [[grid[r][c] for c in range(w)] for r in range(h)]
    bg = grid[0][0]
    fill = 3
    anchor = 5

    for r in range(h):
        anchors = [c for c in range(w) if grid[r][c] == anchor]

        if len(anchors) < 1:
            continue

        # Rule 1: fill between consecutive anchors
        for i in range(len(anchors) - 1):
            start = anchors[i] + 1
            end = anchors[i+1] - 1
            if start <= end:
                for c in range(start, end + 1):
                    if result[r][c] == bg:
                        result[r][c] = fill

        # Rule 2: for single anchors, check if next row has anchor at position + 1
        if len(anchors) == 1:
            anchor_pos = anchors[0]
            # ONLY look at LAST row for this decision
            if r + 1 < h and anchors == anchors_by_row[-1][r+1:]:  # Check if only in R(last+1)
                # NO fill
                pass
            else:
                # Check for anomaly in row N+1
                if r + 1 < h:
                    anchors_down = [c for c in range(w) if grid[r+1][c] == anchor]
                    if anchors_down and not (anchors_down[0] == anchor_pos + 1):
                        # Check if any anchor in LAST row is > current anchor
                        last_row_anchors = [c for c in range(w) if grid[h-1][c] == anchor]
                        if last_row_anchors and min(last_row_anchors) > anchor_pos:
                            for c in range(anchor_pos + 1, anchor_pos + 3):
                                if result[r][c] == bg and c < w:
                                    result[r][c] = fill

    return result

