# Simple rule: fill between consecutive anchors, plus 2 for single anchors when next row doesn't match
def simple_solve(grid):
    h, w = len(grid), len(grid[0])
    result = [[grid[r][c] for c in range(w)] for r in range(h)]
    bg = grid[0][0]
    fill = 3
    anchor = 5

    for r in range(h):
        anchors = [c for c in range(w) if grid[r][c] == anchor]

        if len(anchors) >= 2:
            # Fill between consecutive
            for i in range(len(anchors) - 1):
                start = anchors[i] + 1
                end = anchors[i+1] - 1
                for c in range(start, end + 1):
                    if result[r][c] == bg:
                        result[r][c] = fill
        elif len(anchors) == 1:
            anchor_pos = anchors[0]
            # Check next row
            check_row = r + 1 if r + 1 < h else None
            check_anchors = [c for c in range(w) if grid[check_row][c] == anchor] if check_anchors else []

            # For single anchors: only fill to right if the row below doesn't have an anchor at position + 1
            if check_anchors and check_anchors[0] != anchor_pos + 1:
                # Check if last row has anchors > current
                if h > 1:
                    last_arg = [c for c in range(w) if grid[h-1][c] == anchor]
                    if last_arg and min(last_arg) > anchor_pos:
                        for c in range(anchor_pos + 1, anchor_pos + 3):
                            if result[r][c] == bg and c < w:
                                result[r][c] = fill
                            yield None, None, result
                            return iteration

    return result

