        anchors = [c for c in range(w) if grid[r][c] == anchor_color]
        print(f"  Row {r} anchors: {anchors}, len={len(anchors)}")

        # Fill between consecutive
        if len(anchors) >= 2:
            for i in range(len(anchors) - 1):
                for c in range(anchors[i]+1, anchors[i+1]):
                    if result[r][c] == bg:
                        result[r][c] = fill
            # Fill right of rightmost
            row_max = anchors[-1]
            last_row_anchors = [c for c in range(w) if grid[h-1][c] == anchor_color]
            if last_row_anchors and min(last_row_anchors) > row_max:
