def arc_transform(gi):
    # Grid dimensions
    num_rows = len(gi)
    num_cols = len(gi[0])

    # Create result copy with background color
    ai_results = []
    for ri in range(num_rows):
        ai_result_row = []
        for col_idx in range(num_cols):
            ai_result_row.append(gi[ri][col_idx])
        ai_results.append(ai_result_row)

    bg = gi[0][0]
    color_fill = 3

    # Apply fill rules to each row
    for row_num in range(num_rows):
        # Find anchor positions (value 5)
        anchor_positions = []
        for col_idx in range(num_cols):
            if gi[row_num][col_idx] == 5:
                anchor_positions.append(col_idx)

        sorted_anchors = sorted(anchor_positions)

        if len(sorted_anchors) >= 2:
            # Fill between consecutive anchors
            for anchor_idx in range(len(sorted_anchors) - 1):
                left_anchor = sorted_anchors[anchor_idx]
                right_anchor = sorted_anchors[anchor_idx + 1]
                for fill_col in range(left_anchor + 1, right_anchor):
                    if ai_results[row_num][fill_col] == bg:
                        ai_results[row_num][fill_col] = color_fill

            # Check for right extension (anchors in bottom row beyond current row's rightmost anchor)
            rightmost_anchor = sorted_anchors[-1]
            bottom_row_anchors = []
            for col_idx in range(num_cols):
                if gi[num_rows - 1][col_idx] == 5:
                    bottom_row_anchors.append(col_idx)

            if bottom_row_anchors:
                for bot_anchor in bottom_row_anchors:
                    if bot_anchor > rightmost_anchor:
                        for ext_col in range(bot_anchor - 2, bot_anchor):
                            if ai_results[row_num][ext_col] == bg:
                                ai_results[row_num][ext_col] = color_fill
                        break

        elif len(sorted_anchors) == 1:
            # Single anchor - check if we need right extension
            anchor_pos = sorted_anchors[0]
            if num_rows > 1:
                bottom_row_anchors = []
                for col_idx in range(num_cols):
                    if gi[num_rows - 1][col_idx] == 5:
                        bottom_row_anchors.append(col_idx)

                if bottom_row_anchors:
                    for bot_an in bottom_row_anchors:
                        if bot_an > anchor_pos:
