def solve_complete(grid):
    h, w = len(grid), len(grid[0])
    result = [[grid[r][c] for c in range(w)] for r in range(h)]
    bg = grid[0][0]

    for r in range(h):
        anchors = sorted([c for c in range(w) if grid[r][c] == 5])

        if len(anchors) >= 2:
            # Fill between consecutive anchors
            for i in range(len(anchors) - 1):
                for c in range(anchors[i] + 1, anchors[i + 1]):
                    if result[r][c] == bg:
                        result[r][c] = 3

            # Right extension from last row anchors
            row_max = anchors[-1]
            last_row_anchors = sorted([c for c in range(w) if grid[h - 1][c] == 5])

            if last_row_anchors:
                for last_anch in last_row_anchors:
                    if last_anch > row_max:
                        for c in range(last_anch - 2, last_anch):
                            if result[r][c] == bg and c < w:
                                result[r][c] = 3
                        break
        elif len(anchors) == 1:
            # Single anchor: fill 2 columns to the right IF last row has anchors beyond
            anchor_pos = anchors[0]
            if h > 1:
                last_row_anchors = sorted([c for c in range(w) if grid[h - 1][c] == 5])
                # Check if last row has any anchor to the right of this one
                for last_anch in last_row_anchors:
                    if last_anch > anchor_pos:
                        for c in range(anchor_pos + 1, anchor_pos + 3):
                            if result[r][c] == bg and c < w:
                                result[r][c] = 3
                        break

    return result

